import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;

/**
 * ============================================================================
 *  DO NOT EDIT THIS FILE. It is how you check your own work.
 * ============================================================================
 *
 *  Run it, from a terminal in this folder:
 *
 *      javac *.java
 *      java Verify
 *
 *  (Two commands, every time. There is no build tool in this folder yet, so
 *   IntelliJ cannot reliably launch it for you -- edit there, run here.)
 *
 *  There are 8 checks, grouped by the edit they belong to. When all 8 pass you
 *  are done — you do not need to ask anyone whether it is right.
 *
 *  It will not COMPILE until EDIT 2 is done, because it needs your constructor
 *  to exist. That is expected. Do EDIT 1 and EDIT 2, then run it and work the
 *  failures from the top.
 *
 *  (You have no build tool and no JUnit yet — both arrive later in the module.
 *   This little harness is a stand-in. You will rewrite it as a
 *   real JUnit 5 test suite, which is the best possible reason to learn JUnit.)
 */
public class Verify {

    // ---------- the tiny harness ----------

    private static int passed = 0;
    private static final List<String> failures = new ArrayList<>();

    static void check(String name, boolean condition) {
        System.out.println((condition ? "  PASS  " : "  FAIL  ") + name);
        if (condition) passed++; else failures.add(name);
    }

    static void checkEquals(String name, Object expected, Object actual) {
        boolean ok = expected == null ? actual == null : expected.equals(actual);
        System.out.println((ok ? "  PASS  " : "  FAIL  ") + name);
        if (ok) {
            passed++;
        } else {
            System.out.println("          expected: " + expected);
            System.out.println("          actual:   " + actual);
            failures.add(name);
        }
    }

    /** Runs some code and hands back whatever it printed. */
    static String capture(Runnable action) {
        PrintStream original = System.out;
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        System.setOut(new PrintStream(buffer));
        try {
            action.run();
        } finally {
            System.setOut(original);
        }
        return buffer.toString();
    }

    // ---------- test doubles ----------
    // Note what these are: fake collaborators that record what happened.
    // You could not have written them against the ORIGINAL OrderService,
    // because it built its own. That is the point of the whole session.

    static class RecordingRepository implements OrderRepository {
        final List<Order> saved = new ArrayList<>();
        @Override public void save(Order order) { saved.add(order); }
    }

    static class RecordingSender implements EmailSender {
        final List<String> recipients = new ArrayList<>();
        final List<String> messages = new ArrayList<>();
        @Override public void send(String to, String message) {
            recipients.add(to);
            messages.add(message);
        }
    }

    // ---------- the checks ----------

    public static void main(String[] args) {
        System.out.println();
        System.out.println("Invert OrderService");
        System.out.println("===================");
        System.out.println();

        edits1and2_theInversion();
        behaviourIsUnchanged();
        edits3and4_theAssembler();

        summary();
    }

    static void edits1and2_theInversion() {
        System.out.println("EDITS 1 & 2 - OrderService receives its collaborators");

        boolean fieldsAreInterfaces = true;
        for (Field f : OrderService.class.getDeclaredFields()) {
            if (Modifier.isStatic(f.getModifiers())) continue;
            if (!f.getType().isInterface()) fieldsAreInterfaces = false;
        }
        check("EDIT 1: the fields are interface-typed, not concrete classes",
                fieldsAreInterfaces);

        boolean allFinal = true;
        for (Field f : OrderService.class.getDeclaredFields()) {
            if (Modifier.isStatic(f.getModifiers())) continue;
            if (!Modifier.isFinal(f.getModifiers())) allFinal = false;
        }
        check("EDIT 1: the fields are still final",
                allFinal);

        boolean hasInjectingConstructor = false;
        for (Constructor<?> c : OrderService.class.getDeclaredConstructors()) {
            Class<?>[] p = c.getParameterTypes();
            if (p.length == 2
                    && ((p[0] == OrderRepository.class && p[1] == EmailSender.class)
                     || (p[0] == EmailSender.class && p[1] == OrderRepository.class))) {
                hasInjectingConstructor = true;
            }
        }
        check("EDIT 2: there is a constructor taking (OrderRepository, EmailSender)",
                hasInjectingConstructor);

        System.out.println();
    }

    static void behaviourIsUnchanged() {
        System.out.println("placeOrder still saves, then notifies");

        RecordingRepository repository = new RecordingRepository();
        RecordingSender sender = new RecordingSender();
        OrderService service = new OrderService(repository, sender);

        service.placeOrder(new Order("alice@example.com", 250.00));

        check("the order was handed to the repository",
                repository.saved.size() == 1);

        checkEquals("the email went to the customer",
                "alice@example.com",
                sender.recipients.isEmpty() ? null : sender.recipients.get(0));

        checkEquals("the message is \"Order confirmed\"",
                "Order confirmed",
                sender.messages.isEmpty() ? null : sender.messages.get(0));

        System.out.println();
    }

    static void edits3and4_theAssembler() {
        System.out.println("EDITS 3 & 4 - Main wires two services, one class");

        String output = capture(() -> Main.main(new String[0]));

        check("EDIT 3: Main wired the MySQL repository and emailed alice",
                output.contains("[MySQL] Saving order for alice@example.com totalling $250.00")
             && output.contains("[SMTP] To: alice@example.com | Order confirmed"));

        check("EDIT 4: the SAME OrderService class ran with the in-memory repository",
                output.contains("[Memory] Stored order 1 for bob@example.com")
             && output.contains("[SMTP] To: bob@example.com | Order confirmed"));

        System.out.println();
    }

    static void summary() {
        int total = passed + failures.size();
        System.out.println("---------------------------------------------------");
        if (failures.isEmpty()) {
            System.out.println("  ALL " + total + " CHECKS PASSED");
            System.out.println();
            System.out.println("  Before you close this: EDIT 4 swapped the entire");
            System.out.println("  storage mechanism of the application, and you never");
            System.out.println("  opened OrderService.java to do it. Its source did");
            System.out.println("  not change by one character, and its .class file is");
            System.out.println("  byte-for-byte what it was. That is the whole lesson.");
        } else {
            System.out.println("  " + passed + "/" + total + " passed. Still to fix:");
            for (String f : failures) System.out.println("    - " + f);
        }
        System.out.println("---------------------------------------------------");
        System.out.println();
    }
}
